effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
vec3 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat12;
float u_xlat13;
float u_xlat18;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat12 = _scale * 0.100000001;
    u_xlat18 = float(1.0) / u_xlat12;
    u_xlat1.xy = u_xlat0.xy * vec2(u_xlat18) + vec2(0.5, 0.5);
    u_xlat1.xy = floor(u_xlat1.xy);
    u_xlat1.xy = vec2(u_xlat12) * u_xlat1.xy;
    u_xlat2.xyz = texture(inputImg, u_xlat1.xy).xyz;
    u_xlat18 = u_xlat2.y + u_xlat2.x;
    u_xlat18 = u_xlat2.z + u_xlat18;
    u_xlat18 = (-u_xlat18) * 0.333333343 + 1.0;
    u_xlat18 = log2(u_xlat18);
    u_xlat18 = u_xlat18 * _scale;
    u_xlat18 = exp2(u_xlat18);
    u_xlat12 = u_xlat18 * u_xlat12;
    u_xlat13 = float(1.0) / u_xlat12;
    u_xlat0.xy = u_xlat0.xy * vec2(u_xlat13) + vec2(0.5, 0.5);
    u_xlat0.xy = floor(u_xlat0.xy);
    u_xlat0.xy = (-u_xlat0.xy) * vec2(u_xlat12) + u_xlat1.xy;
    u_xlat1.xy = vec2(u_xlat18) * u_xlat0.xy;
    u_xlat1.xy = u_xlat1.xy * vec2(vec2(_strength, _strength)) + acScreenNorm.xy;
    u_xlat1.xw = texture(inputImg, u_xlat1.xy).xw;
    u_xlat12 = u_xlat18 + _rgb_shift;
    u_xlat2.xy = vec2(u_xlat12) * u_xlat0.xy;
    u_xlat2.xy = u_xlat2.xy * vec2(vec2(_strength, _strength)) + acScreenNorm.xy;
    u_xlat1.y = texture(inputImg, u_xlat2.xy).y;
    u_xlat12 = u_xlat12 + _rgb_shift;
    u_xlat0.xy = vec2(u_xlat12) * u_xlat0.xy;
    u_xlat0.xy = u_xlat0.xy * vec2(vec2(_strength, _strength)) + acScreenNorm.xy;
    u_xlat1.z = texture(inputImg, u_xlat0.xy).z;
    if(int(_use_inner_mask) != 0) {
        u_xlat0 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
